-- challenge chal_coding_acp_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_acp_122', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-1-2' AND is_deleted = false LIMIT 1), 'certificate-eligibility-from-spec', 'Implement the certificate eligibility check from its spec', 'CodeDev is adding course certificates. This time the spec came first and was split into tasks; this is task T1, the eligibility check: a pure function that the API route (task T2) will call later. Implement checkEligibility(course, record) exactly as the spec says, nothing more. course = { courseId, requiredLessons: string[], quizzes: string[] (the course''s quiz challenge ids), quizPassPercent: an integer 0-100, codingChallenges: string[] } comes from the catalog and is valid. record comes from an import file and is untrusted. 1. Validation: the record is invalid when it is not an object (null, an array, a string ...), when userId is not a string with at least one non-space character, when completedLessons, passedQuizzes or passedCoding is missing or is not an array of strings, when revoked is not a boolean, or when issuedAt is neither null nor a number (a timestamp in ms; null means never issued). An invalid record gives { eligible: false, reasons: ["invalid_record"] } and no other reason. 2. Otherwise collect every reason that applies, in this fixed order: "lessons_incomplete" when a lesson in requiredLessons is not in completedLessons; "quiz_rate_too_low" when (number of the course''s quiz ids found in passedQuizzes) * 100 < quizPassPercent * (number of course quizzes) - compare with whole numbers like this, so a rate exactly at the threshold passes, ids from other courses do not count and a course with no quizzes passes this rule; "coding_not_passed" when a challenge in codingChallenges is not in passedCoding; "revoked" when revoked is true; "already_issued" when issuedAt is not null (a certificate is issued once). Ids are compared exactly (case-sensitive, no trimming) and duplicates in the learner''s lists count once. 3. eligible is true exactly when reasons is empty. Input (stdin, JSON): { course, records: unknown[] }. Output: the runner prints one JSON array with { userId, eligible, reasons } per record, in input order (userId is null when the record has no string userId). Up to a few hundred records; standard library only.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
