INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_122'), 1, 'For each sentence of the spec, which record would break it? Then look for records that break several rules at once: what does the spec say the output contains then, and in which order?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_122'), 2, 'Look at three places. Validation runs before every other rule and checks the type of each field: a list can exist and still contain a number, and 0 is a valid timestamp that is not null. The quiz rule counts the course''s quiz ids the learner passed, not the length of the learner''s list, and compares with whole numbers. The reasons are pushed in the spec''s order and none of them stops the others.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_122'), 3, 'A similar spec on different data: a mentor badge needs the required reviews r1, r2, r3, at least 50% of the course''s forum questions f1-f4 answered, and banned false; reasons in the order reviews_missing, answer_rate_too_low, banned. A learner with reviews [r1, r1, r2, r3], answers [f1, f1, x9] and banned true gets [answer_rate_too_low, banned]: the duplicate r1 changes nothing, f1 counts once and x9 belongs to another course, so 1 * 100 < 50 * 4.');
