-- challenge chal_quiz_acp_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_acp_131', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-1-3' AND is_deleted = false LIMIT 1), 'instruction-files-quiz', 'Does the instruction file do its job?', 'Three pieces of evidence from the CodeDev repository: an agent session that used a command from AGENTS.md, a single test of a new never-rule, and a pull request that failed CI after following "Done means".', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131'), 'AGENTS.md, line 66:
  - Run the unit tests: `yarn test:unit`

package.json:
  "scripts": { "test": "vitest run", "lint": "eslint .", "verify": "npm run typecheck && npm run lint && npm test" }

Agent session log:
  read  AGENTS.md
  run   yarn test:unit
        -> yarn: error Command "test:unit" not found.
  done  "The unit test command is not available in this environment, so I
         reviewed the change manually. The refactoring is complete."

Statement: "The tests were not run because the agent ignored the instruction file."', 'single_choice'::question_type, 'False. The log shows the opposite: the agent read AGENTS.md and ran exactly the command on line 66. The file is wrong - the repository has no yarn setup and no test:unit script - so following it led to a failure, and with no working feedback the agent fell back on its own judgement and declared the task done. The fix is in the file (a command that exists, ideally the same npm run verify that CI runs, checked by a script), plus a "done" rule that does not let "command not found" end a task. The misconception is that bad agent behavior always means the agent disobeyed; an instruction file that lies is followed into failure.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131'), 'A line added to AGENTS.md on Monday:
  - Never edit a migration that exists on main; add a new one instead.

Test done by the tech lead on Tuesday: one task that needs a new column, one session with one agent.

$ git diff --name-status origin/main...agent/add-course-language
A       db/migrations/20261027_001_course_language.sql
M       lib/catalog/course.ts
M       tests/catalog/course.test.ts

Statement: "This session shows that agents follow the new rule, so the rule does not also need a check in CI."', 'single_choice'::question_type, 'False. One session of a non-deterministic agent, on one task, with one tool and one model, is a single sample: the same file can be followed twice and skipped the third time, especially on a task where editing the old migration looks like the shortest path. An instruction line is feedforward; a rule whose violation is costly also needs feedback that cannot be skipped, such as a check that fails on any modified or deleted file under db/migrations/ that exists on main. To know how well a rule is followed, run a small task set several times and score the runs with a script. The misconception is that one good run proves compliance.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131'), 'AGENTS.md:
  ## Done means
  - `npm test` and `npm run lint` pass; show their output.

.github/workflows/ci.yml (steps):
  - run: npm ci
  - run: npm run typecheck
  - run: npm run lint
  - run: npm test
  - run: npm run db:verify

The agent''s PR: its log shows npm test and npm run lint passing. CI fails:
  npm run typecheck
  lib/catalog/course.ts(41,7): error TS2322: Type ''string | undefined'' is not assignable to type ''string''.

Statement: "The agent followed the instruction file; the PR failed because the file''s definition of done is out of sync with what CI checks."', 'single_choice'::question_type, 'True. The agent did what "Done means" asked, and both commands passed. CI checks two more things, typecheck and db:verify, that the instruction file never mentions, so the agent had no reason to run them. The durable fix is one command for both: an npm run verify script that runs everything CI runs, named in AGENTS.md and run by CI, plus a small check that fails when the two drift apart. The misconception is that an instruction file and CI are maintained separately; when they disagree, agents keep finishing tasks that CI then rejects.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_131') AND order_index = 3)
    RETURNING id
)
