-- lesson 2.2: Feedback loops: tests, lint & choosing which tests to run (Sanity lesson-acp-2-2)
UPDATE course.lesson SET title = 'Feedback loops: tests, lint & choosing which tests to run', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 2 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-2-2' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 2 AND is_deleted = false LIMIT 1), 'Feedback loops: tests, lint & choosing which tests to run', 'sanity', 'lesson-acp-2-2', 2
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-acp-2-2' AND is_deleted = false);

-- challenge chal_quiz_acp_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_acp_221', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-2-2' AND is_deleted = false LIMIT 1), 'tests-as-feedback-quiz', 'Was the agent''s feedback good enough?', 'Two agent sessions on the CodeDev API: a green test run next to a type error, and a fast test run that missed two failing tests.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_221'), 'package.json (scripts)
  "test": "vitest run",
  "typecheck": "tsc --noEmit"

.github/workflows/ci.yml (steps)
  - run: npm ci
  - run: npm test

Agent session after changing percent() in src/progress/percent.ts to return number | null:
$ npm test
 Test Files  38 passed (38)
      Tests  214 passed (214)
$ npx tsc --noEmit
src/api/progressRoute.ts:22:5 - error TS2322: Type ''number | null'' is not assignable to type ''number''.

Statement: "All 214 tests passed after Vitest ran the edited code, so the tsc error is a false alarm, and adding npm run typecheck to the agent''s checks and to CI would catch nothing new."', 'single_choice'::question_type, 'False. Passing tests and passing the type checker are different signals. By default Vitest transforms TypeScript by removing the types without checking them, so a test run can be green while tsc reports an error. Here the error is real: progressRoute.ts passes a value that can now be null to code that expects a number, and no test covers that path. CI only runs npm test, so the error would reach main. Adding the typecheck to the agent''s loop and to CI catches exactly this kind of mistake, in seconds. The misconception is that "the tests compiled and passed" means the types are correct.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_221'), 'Agent session, task "make course slugs lowercase":
$ git diff --name-only
src/courses/slug.ts
$ npx vitest run test/courses
 Test Files  3 passed (3)
   Duration  2.2s
Agent: "Done, all tests pass."

CI, full suite, 12 minutes later:
 FAIL  test/api/enroll.test.ts > enrolls by course slug
 FAIL  test/sitemap/sitemap.test.ts > lists every published course

Imports:
test/api/enroll.test.ts -> src/api/enroll.ts -> src/courses/lookup.ts -> src/courses/slug.ts
test/sitemap/sitemap.test.ts -> src/sitemap/build.ts -> src/courses/lookup.ts

Statement: "Choosing the tests by following imports back from the changed file, instead of by folder name, would have run both failing tests in the agent''s own loop, before it said it was done."', 'single_choice'::question_type, 'True. Both failing tests depend on slug.ts: enroll.test.ts through enroll.ts -> lookup.ts -> slug.ts, and sitemap.test.ts through build.ts -> lookup.ts -> slug.ts. A selection that walks the import graph from the changed file finds every test that can observe the change, wherever it lives; a selection by folder name only finds the tests that happen to sit in test/courses. The agent''s loop was fast but blind, and the real feedback came 12 minutes later in CI, after the agent had reported success. The misconception is that the tests for a module live next to it; the tests that break are often the ones for the module''s callers.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_acp_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_acp_222', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-2-2' AND is_deleted = false LIMIT 1), 'select-tests-to-run', 'Choose which tests to run after an edit', 'CodeDev''s coding agent runs the relevant tests after every edit and leaves the full suite to CI. Choosing the tests by folder name missed the tests of other modules that use the changed code, so write selectTests(repo), which chooses them from the import graph. The input is one JSON object:
- "changed": [{ "path": string, "status": "added" | "modified" | "deleted" }] - the files the agent changed. A path can appear more than once.
- "imports": { file: [files it imports] } and "tests": { testFile: [files it imports] } - the repository after the change. A file that is not a key of imports imports nothing. Imports may point to files that no longer exist (a deleted file that is still imported) and may form cycles, including a file that imports itself.
- "runAll": [paths] - config files and lockfiles: a change to any of them, with any status, runs every test.

Rules:
- A test file reaches itself, every file in its tests entry, and every file those files import, transitively.
- "all" is true when a changed path is in runAll. Then "tests" is every key of tests. Otherwise "tests" is every test file that reaches at least one changed path (a deleted path included: tests that still import a deleted file must run and show the broken import).
- "untested": the changed paths that no test file reaches, leaving out deleted paths and paths in runAll (computed the same way whether or not "all" is true). The agent reports these instead of claiming they are tested.
- "tests" and "untested" are sorted by plain string comparison (code-unit order, as Array.prototype.sort does with no comparator) and have no duplicates.

Output: the test runner prints { "all": boolean, "tests": string[], "untested": string[] } as JSON. Paths are compared as exact strings. The largest repository has about 750 files and 120 test files.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
