INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_222'), 1, 'For one test file, how would you list every file whose change could make that test fail? And what stops that walk from going round forever when two files import each other?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_222'), 2, 'Write one walk over imports with a stack and a seen set, starting from a test file. Run it for each test file, then compare the files it reached with the changed paths. Look again at deleted paths: they still count for selecting tests but not for untested.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_222'), 3, 'A similar graph: test/x.test.ts imports src/x.ts, src/x.ts imports src/y.ts, src/y.ts imports src/x.ts. Starting from test/x.test.ts the walk visits test/x.test.ts, src/x.ts, src/y.ts, then sees src/x.ts again and stops. A change to src/y.ts therefore selects test/x.test.ts; a change to src/z.ts selects nothing and src/z.ts is untested.');
