VALUES ('chal_quiz_acp_311', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-3-1' AND is_deleted = false LIMIT 1), 'agent-command-privilege-quiz', 'Which commands may the agent run?', 'Two pieces of evidence from the migration incident: the terminal the agent was started in, and the first command check the harness used.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
