INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_312'), 1, 'What is "the command" the policy judges: the first program in the string, or every program the shell would start? Where exactly does the shell end one program and start the next, and what does a quote change about that?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_312'), 2, 'Keep three steps apart. A lexer that walks the string one character at a time, building the current word and remembering whether a word has started (so '''' still produces a word) and emitting operator tokens. A splitter that cuts the tokens at operators and remembers which operator came before each segment. A per-segment judge that skips leading NAME=value words, then tries the rules in the listed order and returns at the first match. Combine the segment verdicts only at the end: deny beats ask, ask beats allow.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_312'), 3, 'A worked trace on another line: A=1 make check | ''zsh'' -e ; echo "x;y". Tokens: A=1, make, check, |, zsh, -e, ;, echo, x;y (the ; inside double quotes is text). Segments: [A=1 make check] with no operator before it, [zsh -e] after |, [echo x;y] after ;. Verdicts: make is not on the allow list -> ask unknown; zsh right after | -> deny pipe-to-shell; echo -> ask unknown. The line: deny, pipe-to-shell.');
