-- lesson 3.2: Keep the agent in scope: allowed paths & reviewable diffs (Sanity lesson-acp-3-2)
UPDATE course.lesson SET title = 'Keep the agent in scope: allowed paths & reviewable diffs', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 3 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-3-2' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 3 AND is_deleted = false LIMIT 1), 'Keep the agent in scope: allowed paths & reviewable diffs', 'sanity', 'lesson-acp-3-2', 2
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-acp-3-2' AND is_deleted = false);

-- challenge chal_quiz_acp_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_acp_321', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-3-2' AND is_deleted = false LIMIT 1), 'agent-change-scope-quiz', 'Did the agent stay in scope?', 'Two diffs from agent PRs on the catalog: one with a rename the first scope check missed, one with a file the allowed glob does not cover.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
