INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_322'), 1, 'When a file is renamed, which paths did the change touch: only where the file is now, or also where it was? And when a path matches both an allowed and a forbidden pattern, which one wins - does it depend on the forbidden entry?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_322'), 2, 'Split the work. Expand the braces into a list of plain patterns. Compare a pattern with a path segment by segment, letting a "**" segment take zero, one or more path segments (a small recursive function over two indexes does it). Inside one segment translate * and ? and escape every other character if you build a regular expression - ( [ . + mean something to RegExp. Then check each path in the order invalid, forbidden, allowed, and sort at the end with a comparator on path, then change.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_322'), 3, 'A worked example with another pattern: docs/**/{intro,faq}.md expands to docs/**/intro.md and docs/**/faq.md. Against docs/faq.md: docs = docs, ** takes zero segments, faq.md = faq.md, so it matches. Against docs/v2/guides/intro.md: ** takes v2 and guides, it matches. Against docs/intro.mdx: intro.md is not intro.mdx, no match. And docs/*.md against docs/v2/intro.md: one * cannot take v2/intro, no match.');
