INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_acp_412', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-4-1' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-admin-api-owner-check', 'Spot the AI Mistake: an admin API without an owner check', 'The CodeDev course studio was vibe-coded in a weekend. The request sent to the coding agent was: "Add an edit endpoint for courses in the course studio. Only instructors can edit. Keep it simple, the demo is on Monday." Its handler updateCourse (PATCH /api/courses/:id, plain TypeScript with an in-memory store and sessions that the auth middleware has already resolved) passes the agent''s tests, but on Monday instructor Binh edited a course owned by instructor Ana, and a request from Binh with "ownerId" in the body moved another of Ana''s courses to him. Fix updateCourse so that it follows this policy, checked in this order: (1) no user (missing or unknown session): 401 {"error":"unauthenticated"}; (2) a role other than instructor or admin: 403 {"error":"forbidden"}; (3) a body that is not a JSON object (null, an array, a string): 400 {"error":"invalid_body"}; (4) the course does not exist, or the caller is an instructor who does not own it (course.ownerId differs from user.id): 404 {"error":"not_found"}, the same answer in both cases so that the API does not reveal which course ids exist; an admin may edit any course; (5) the body keys, in their order: a key other than title, description and price (id, ownerId, createdAt or any unknown field) gives 400 {"error":"field_not_editable","field":<key>}; an invalid value gives 400 {"error":"invalid_field","field":<key>} (title: a string that is not blank, description: a string, price: an integer >= 0); the first failing key decides; (6) otherwise 200 with the updated course, in which only the keys of the body changed. A rejected request changes nothing, and nobody can change ownerId through this endpoint, not even an admin. The test runner sends a list of requests, prints one line per request (status and error) and then every course in the store. The public tests pass on the agent''s code; the hidden tests use a second instructor, ownerId in the body, a missing course and an admin.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 1, 'The agent''s code asks two questions about the caller: is there a session, and is the role instructor or admin? Which question about this particular course does it never ask, and which keys of the body can end up in the stored course?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 2, 'Look at the lines between `courses.get(req.params.id)` and the spread `{ ...course, ...changes }`. Which field of the course says whose it is, and what does the loop over the body do with a key it does not recognise?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 3, 'A similar case on another resource: announcements { id, authorId, text, pinned }. `const a = store.get(id); if (!a || (user.role !== "admin" && a.authorId !== user.id)) return { status: 404 };` treats "missing" and "not yours" the same. For PATCH, a list of allowed keys such as `new Set(["text"])` rejects `authorId` and `pinned` before anything is copied.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'The owner edits her own course, another instructor edits his own', '[{"session":"sess_ana","courseId":"c_101","body":{"title":"SQL for Absolute Beginners","price":79000}},{"session":"sess_binh","courseId":"c_201","body":{"description":"Images, containers and volumes."}}]', '"#1 PATCH /api/courses/c_101 as u_ana: 200 ok\n#2 PATCH /api/courses/c_201 as u_binh: 200 ok\nc_101: id=c_101 owner=u_ana title=\"SQL for Absolute Beginners\" description=\"Tables, SELECT and WHERE.\" price=79000 createdAt=2026-09-01\nc_102: id=c_102 owner=u_ana title=\"Indexes in Practice\" description=\"B-trees and query plans.\" price=149000 createdAt=2026-09-15\nc_201: id=c_201 owner=u_binh title=\"Docker Basics\" description=\"Images, containers and volumes.\" price=0 createdAt=2026-10-02"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'Anonymous, learner, a negative price and a blank title are rejected', '[{"session":null,"courseId":"c_101","body":{"title":"Hacked"}},{"session":"sess_lan","courseId":"c_101","body":{"title":"Hacked"}},{"session":"sess_ana","courseId":"c_102","body":{"price":-5}},{"session":"sess_ana","courseId":"c_102","body":{"title":"   "}}]', '"#1 PATCH /api/courses/c_101 as anonymous: 401 unauthenticated\n#2 PATCH /api/courses/c_101 as u_lan: 403 forbidden\n#3 PATCH /api/courses/c_102 as u_ana: 400 invalid_field (price)\n#4 PATCH /api/courses/c_102 as u_ana: 400 invalid_field (title)\nc_101: id=c_101 owner=u_ana title=\"SQL for Beginners\" description=\"Tables, SELECT and WHERE.\" price=99000 createdAt=2026-09-01\nc_102: id=c_102 owner=u_ana title=\"Indexes in Practice\" description=\"B-trees and query plans.\" price=149000 createdAt=2026-09-15\nc_201: id=c_201 owner=u_binh title=\"Docker Basics\" description=\"Images and containers.\" price=0 createdAt=2026-10-02"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'A second instructor cannot edit another instructor''s courses: 404, nothing changes', '[{"session":"sess_binh","courseId":"c_101","body":{"title":"Binh was here"}},{"session":"sess_binh","courseId":"c_102","body":{"price":0}},{"session":"sess_binh","courseId":"c_201","body":{"title":"Docker in Practice"}}]', '"#1 PATCH /api/courses/c_101 as u_binh: 404 not_found\n#2 PATCH /api/courses/c_102 as u_binh: 404 not_found\n#3 PATCH /api/courses/c_201 as u_binh: 200 ok\nc_101: id=c_101 owner=u_ana title=\"SQL for Beginners\" description=\"Tables, SELECT and WHERE.\" price=99000 createdAt=2026-09-01\nc_102: id=c_102 owner=u_ana title=\"Indexes in Practice\" description=\"B-trees and query plans.\" price=149000 createdAt=2026-09-15\nc_201: id=c_201 owner=u_binh title=\"Docker in Practice\" description=\"Images and containers.\" price=0 createdAt=2026-10-02"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'ownerId in the body: no takeover, and id, ownerId, createdAt are not editable by the owner', '[{"session":"sess_binh","courseId":"c_102","body":{"ownerId":"u_binh","title":"Indexes (test)"}},{"session":"sess_ana","courseId":"c_102","body":{"title":"Indexes in Practice, 2nd ed.","ownerId":"u_binh"}},{"session":"sess_ana","courseId":"c_101","body":{"id":"c_999"}},{"session":"sess_ana","courseId":"c_101","body":{"createdAt":"2020-01-01"}}]', '"#1 PATCH /api/courses/c_102 as u_binh: 404 not_found\n#2 PATCH /api/courses/c_102 as u_ana: 400 field_not_editable (ownerId)\n#3 PATCH /api/courses/c_101 as u_ana: 400 field_not_editable (id)\n#4 PATCH /api/courses/c_101 as u_ana: 400 field_not_editable (createdAt)\nc_101: id=c_101 owner=u_ana title=\"SQL for Beginners\" description=\"Tables, SELECT and WHERE.\" price=99000 createdAt=2026-09-01\nc_102: id=c_102 owner=u_ana title=\"Indexes in Practice\" description=\"B-trees and query plans.\" price=149000 createdAt=2026-09-15\nc_201: id=c_201 owner=u_binh title=\"Docker Basics\" description=\"Images and containers.\" price=0 createdAt=2026-10-02"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'A missing course is 404; the session and role are checked before the course lookup', '[{"session":"sess_ana","courseId":"c_404","body":{"title":"Ghost"}},{"session":"sess_admin","courseId":"c_404","body":{"title":"Ghost"}},{"session":"sess_lan","courseId":"c_404","body":{"title":"Ghost"}},{"session":"sess_expired","courseId":"c_404","body":{"title":"Ghost"}}]', '"#1 PATCH /api/courses/c_404 as u_ana: 404 not_found\n#2 PATCH /api/courses/c_404 as u_admin: 404 not_found\n#3 PATCH /api/courses/c_404 as u_lan: 403 forbidden\n#4 PATCH /api/courses/c_404 as anonymous: 401 unauthenticated\nc_101: id=c_101 owner=u_ana title=\"SQL for Beginners\" description=\"Tables, SELECT and WHERE.\" price=99000 createdAt=2026-09-01\nc_102: id=c_102 owner=u_ana title=\"Indexes in Practice\" description=\"B-trees and query plans.\" price=149000 createdAt=2026-09-15\nc_201: id=c_201 owner=u_binh title=\"Docker Basics\" description=\"Images and containers.\" price=0 createdAt=2026-10-02"', 2, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_412'), 'An admin may edit any course but cannot change its owner', '[{"session":"sess_admin","courseId":"c_201","body":{"title":"Docker Basics (reviewed)","price":49000}},{"session":"sess_admin","courseId":"c_101","body":{"ownerId":"u_admin"}},{"session":"sess_admin","courseId":"c_102","body":{"description":"B-trees, query plans and EXPLAIN."}}]', '"#1 PATCH /api/courses/c_201 as u_admin: 200 ok\n#2 PATCH /api/courses/c_101 as u_admin: 400 field_not_editable (ownerId)\n#3 PATCH /api/courses/c_102 as u_admin: 200 ok\nc_101: id=c_101 owner=u_ana title=\"SQL for Beginners\" description=\"Tables, SELECT and WHERE.\" price=99000 createdAt=2026-09-01\nc_102: id=c_102 owner=u_ana title=\"Indexes in Practice\" description=\"B-trees, query plans and EXPLAIN.\" price=149000 createdAt=2026-09-15\nc_201: id=c_201 owner=u_binh title=\"Docker Basics (reviewed)\" description=\"Images and containers.\" price=49000 createdAt=2026-10-02"', 3, false, true, 6),
