    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_421'), '.gitignore:
.env*.local

.env.local (on the build machine, never committed):
NEXT_PUBLIC_AI_API_KEY=sk-fake-4f9a1c7e2b8d6a0f93e1

Statement: "Because .env.local is git-ignored, the key stays on the build machine and the server, and visitors of the site cannot read it."', 'single_choice'::question_type, 'False. .gitignore only keeps the file out of the repository. The NEXT_PUBLIC_ prefix tells Next.js to copy the variable''s value into the JavaScript built for the browser wherever client code reads it, so the value is published with every deploy, whatever file it came from. A variable without the prefix stays on the server, which is where an API key belongs. The misconception is to treat "not in git" as "secret"; the question to ask is which code reads the value and where that code runs.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_acp_421') AND order_index = 2)
    RETURNING id
)
