-- challenge chal_coding_acp_422 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_acp_422', (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'agentic-coding-practice') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-acp-4-2' AND is_deleted = false LIMIT 1), 'move-the-api-key-out-of-the-frontend', 'Vibe-coded app: the AI key in the client bundle', 'The CodeDev course studio has a "Suggest an outline" button. The coding agent first wrote a server route for it, saw it answer 401 in the demo, removed the session check, and then made the browser call the AI vendor directly with the key in NEXT_PUBLIC_AI_API_KEY. The vendor now reports the key in use from addresses that are not CodeDev''s. The file models the app as two modules, marked CLIENT (everything inside the `client` object is bundled and shipped to every browser; the build inlines each `publicEnv.NEXT_PUBLIC_*` it reads) and SERVER (the `server` object, which may read `serverEnv`), plus a fake network and a bundle scanner. Fix both modules so that: (1) client.suggestOutline(title) sends exactly one request, POST /api/outline (the same-origin path, which carries the user''s session cookie) with the JSON body {"title": title}, and returns {ok: true, outline} for a 200 or {ok: false, status, error} with the error string of the response otherwise; (2) server.postOutline answers, checked in this order: no user (req.user is null) 401 {"error":"unauthenticated"}; a body that is not JSON or whose title is not a string of 1 to 120 characters after trimming 400 {"error":"invalid_title"}; more than 5 accepted requests by the same user in the same minute 429 {"error":"rate_limited"} (fixed window: Math.floor(clock.now / 60000); each user has their own counter; requests rejected with 401 or 400 do not count); otherwise it calls the AI vendor with the key from serverEnv.AI_API_KEY and the trimmed title as topic (3 sections, as the agent''s route already does) and returns 200 {"outline": sections}, or 502 {"error":"upstream_error"} if the vendor fails; (3) no string the browser can reach contains the key: the client must not read publicEnv.NEXT_PUBLIC_AI_API_KEY, serverEnv or ENV, or keep the key in any property. The test runner prints, for each step, the result and the requests the browser sent (a request that carries the key is marked), the bundle scanner''s findings when asked, and finally how many AI calls came from the server and from browsers. The hidden tests scan the bundle, call the route without a session and check the per-user limit and invalid titles.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 1, 'Who should hold the AI key: the code that runs in every visitor''s browser, or the code that runs on your server? And once the server makes the call for the browser, who decides which callers it makes it for?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 2, 'Look at the URL and the headers in client.suggestOutline, and at the first lines of server.postOutline (the comment says what the agent removed). The route also needs a counter per user and per minute before it calls the vendor.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 3, 'A similar case: a translation button that called https://translate.example/v2 with publicEnv.NEXT_PUBLIC_TRANSLATE_KEY. The fix sends POST /api/translate {"text"} from the browser; the route returns 401 without a user, keeps a counter keyed by the user id and Math.floor(now / 60000) below its limit of 20, and only then reads serverEnv.TRANSLATE_KEY to call the vendor.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'Two logged-in instructors get an outline from the studio', '[{"browser":"sess_ana","title":"SQL Joins"},{"browser":"sess_binh","title":"Docker Volumes"}]', '"#1 browser of u_ana: 200 Why SQL Joins matters | SQL Joins step by step | Practice: SQL Joins; requests: POST /api/outline\n#2 browser of u_binh: 200 Why Docker Volumes matters | Docker Volumes step by step | Practice: Docker Volumes; requests: POST /api/outline\nAI vendor calls: from the server 2, from browsers 0"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'The bundle scanner checks what ships to the browser', '[{"browser":"sess_ana","title":"Indexes"},{"scan":true}]', '"#1 browser of u_ana: 200 Why Indexes matters | Indexes step by step | Practice: Indexes; requests: POST /api/outline\n#2 bundle scan: no secrets\nAI vendor calls: from the server 1, from browsers 0"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'Anonymous callers are rejected and never reach the AI vendor', '[{"browser":null,"title":"SQL Joins"},{"curl":null,"body":"{\"title\":\"Free AI for everyone\"}"},{"curl":"sess_expired","body":"{\"title\":\"Free AI for everyone\"}"},{"curl":"sess_ana","body":"{\"title\":\"Window Functions\"}"}]', '"#1 browser of anonymous: 401 unauthenticated; requests: POST /api/outline\n#2 curl as anonymous: 401 unauthenticated\n#3 curl as anonymous: 401 unauthenticated\n#4 curl as u_ana: 200 Why Window Functions matters | Window Functions step by step | Practice: Window Functions\nAI vendor calls: from the server 1, from browsers 0"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'Five outlines per user per minute, counted for each user separately', '[{"browser":"sess_ana","title":"Topic 1"},{"browser":"sess_ana","title":"Topic 2"},{"browser":"sess_ana","title":"Topic 3"},{"browser":"sess_ana","title":"Topic 4"},{"browser":"sess_ana","title":"Topic 5"},{"browser":"sess_ana","title":"Topic 6"},{"browser":"sess_binh","title":"Docker Volumes"},{"curl":"sess_ana","body":"{\"title\":\"Topic 7\"}"},{"advance":60000},{"browser":"sess_ana","title":"Topic 8"}]', '"#1 browser of u_ana: 200 Why Topic 1 matters | Topic 1 step by step | Practice: Topic 1; requests: POST /api/outline\n#2 browser of u_ana: 200 Why Topic 2 matters | Topic 2 step by step | Practice: Topic 2; requests: POST /api/outline\n#3 browser of u_ana: 200 Why Topic 3 matters | Topic 3 step by step | Practice: Topic 3; requests: POST /api/outline\n#4 browser of u_ana: 200 Why Topic 4 matters | Topic 4 step by step | Practice: Topic 4; requests: POST /api/outline\n#5 browser of u_ana: 200 Why Topic 5 matters | Topic 5 step by step | Practice: Topic 5; requests: POST /api/outline\n#6 browser of u_ana: 429 rate_limited; requests: POST /api/outline\n#7 browser of u_binh: 200 Why Docker Volumes matters | Docker Volumes step by step | Practice: Docker Volumes; requests: POST /api/outline\n#8 curl as u_ana: 429 rate_limited\n#9 clock +60s\n#10 browser of u_ana: 200 Why Topic 8 matters | Topic 8 step by step | Practice: Topic 8; requests: POST /api/outline\nAI vendor calls: from the server 7, from browsers 0"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'No secret in the bundle before and after anonymous and logged-in calls', '[{"scan":true},{"browser":null,"title":"SQL Joins"},{"curl":"sess_binh","body":"{\"title\":\"Caching\"}"},{"scan":true}]', '"#1 bundle scan: no secrets\n#2 browser of anonymous: 401 unauthenticated; requests: POST /api/outline\n#3 curl as u_binh: 200 Why Caching matters | Caching step by step | Practice: Caching\n#4 bundle scan: no secrets\nAI vendor calls: from the server 1, from browsers 0"', 2, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_acp_422'), 'Invalid bodies and titles get 400 and do not use up the limit', '[{"curl":"sess_ana","body":"not json"},{"curl":"sess_ana","body":"{\"title\":42}"},{"curl":"sess_ana","body":"{\"title\":\"   \"}"},{"curl":"sess_ana","body":"{\"title\":\"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\"}"},{"curl":"sess_ana","body":"null"},{"curl":"sess_ana","body":"[]"},{"curl":"sess_ana","body":"{}"},{"curl":null,"body":"not json"},{"browser":"sess_ana","title":"  Spaced Title  "},{"curl":"sess_ana","body":"{\"title\":\"yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy\"}"},{"browser":"sess_ana","title":"Topic 3"},{"browser":"sess_ana","title":"Topic 4"},{"browser":"sess_ana","title":"Topic 5"},{"browser":"sess_ana","title":"Topic 6"}]', '"#1 curl as u_ana: 400 invalid_title\n#2 curl as u_ana: 400 invalid_title\n#3 curl as u_ana: 400 invalid_title\n#4 curl as u_ana: 400 invalid_title\n#5 curl as u_ana: 400 invalid_title\n#6 curl as u_ana: 400 invalid_title\n#7 curl as u_ana: 400 invalid_title\n#8 curl as anonymous: 401 unauthenticated\n#9 browser of u_ana: 200 Why Spaced Title matters | Spaced Title step by step | Practice: Spaced Title; requests: POST /api/outline\n#10 curl as u_ana: 200 Why yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy matters | yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy step by step | Practice: yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy\n#11 browser of u_ana: 200 Why Topic 3 matters | Topic 3 step by step | Practice: Topic 3; requests: POST /api/outline\n#12 browser of u_ana: 200 Why Topic 4 matters | Topic 4 step by step | Practice: Topic 4; requests: POST /api/outline\n#13 browser of u_ana: 200 Why Topic 5 matters | Topic 5 step by step | Practice: Topic 5; requests: POST /api/outline\n#14 browser of u_ana: 429 rate_limited; requests: POST /api/outline\nAI vendor calls: from the server 5, from browsers 0"', 2, false, true, 6),
